import { isCurrencyMath } from '@mintlify/common';
import katex from 'katex';
import { visit } from 'unist-util-visit';

import type { FileRule, FileFinding } from '../../types.js';

export const katexRule: FileRule = {
  id: 'katex',
  group: 'content',
  severity: 'warning',
  scope: 'file',
  description: "math that KaTeX can't render",
  check: ({ tree, content }) => {
    const issues: FileFinding[] = [];
    visit(tree, (node) => {
      if (node.type !== 'math' && node.type !== 'inlineMath') return;
      if (node.type === 'inlineMath' && isCurrencyMath(node, content)) return;
      try {
        katex.renderToString(node.value, {
          throwOnError: true,
          displayMode: node.type === 'math',
        });
      } catch (error) {
        issues.push({
          line: node.position?.start.line,
          column: node.position?.start.column,
          message: error instanceof Error ? error.message : 'invalid math',
        });
      }
    });
    return issues;
  },
};
